/* Case-insensitive; NULL if this SGBD has no row (unknown or no overrides at all). */
static inline const struct dme_sgbd_row *dme_signal_row(const char *sgbd) {
    unsigned i;
    if (!sgbd) return 0;
    for (i = 0; i < sizeof dme_signal_table / sizeof dme_signal_table[0]; ++i)
        if (!strcasecmp(sgbd, dme_signal_table[i].sgbd)) return &dme_signal_table[i];
    return 0;
}

